fn bootstrap_user_entry()->Vec<u8>{
    let properties=[RpcProperty{key:b"DomainName",value:b"account-domain.invalid"},RpcProperty{key:b"DomainId",value:b"fixture-domain"},RpcProperty{key:b"AppId",value:b"fixture-app"},RpcProperty{key:b"CC",value:b"fixture-cc"}];
    let mut w=Writer::new();w.boolean(true).unwrap();w.properties(&properties).unwrap();w.bytes(DESTINATION.as_bytes()).unwrap();w.bytes(b"").unwrap();w.bytes(b"prefix/UserEntry:sarc -h 42.7 -p 98;").unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()
}
fn answer(mode:u8)->Vec<u8>{let mut w=Writer::new();w.boolean(mode!=1).unwrap();w.u32(if mode==2{0}else if mode==4{2}else{1}).unwrap();if mode!=2{w.bytes(b"7_9").unwrap();w.bytes(b"phone").unwrap();w.bytes(if mode==3{b"+67890"}else{b"+12345"}).unwrap();if mode==4{w.bytes(b"8_9").unwrap();w.bytes(b"phone").unwrap();w.bytes(b"+12345").unwrap();}}w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
async fn logout_peer(mut peer:CommonPeer){loop{let packet=peer.next().await.unwrap();let call=decode_request(&packet[1..]).unwrap();if call.method==b"logoutSession.AccountEntry.Account"{assert_eq!(call.metadata.iter().find(|p|p.key==b"id").unwrap().value,b"DestEntry");peer.send(&[reply(call.call_id,b"\0\x01\0\0\0\0")]).await;break;}assert_eq!(call.method,super::super::super::rpc_batch::SWAP_CALLS_METHOD.as_bytes());let mut args=Reader::versioned(call.arguments).unwrap();args.bytes().unwrap();args.bytes().unwrap();let data=super::super::super::rpc_batch::read_payload(&mut args).unwrap();let sequence=data.requests.keys().copied().max();peer.send(&[reply(call.call_id,&super::super::tests::swap_result(sequence,true,data.fields))]).await;}peer.no_more_common().await;}
async fn scenario(mode:u8){
    let cert=Certificates::generate("IP:127.0.0.1");let front=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=front.local_addr().unwrap().port();
    let boot=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let main=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let auxiliary=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let ports=[boot.local_addr().unwrap().port(),main.local_addr().unwrap().port(),auxiliary.local_addr().unwrap().port()];
    let config=cert.server_config(&TLS13);let boot_config=config.clone();let main_config=config.clone();let(seen,submitted)=oneshot::channel();
    let relay=tokio::spawn(async move{let mut joins=Vec::new();for target in ports{let(mut inbound,_)=front.accept().await.unwrap();let mut outbound=tokio::net::TcpStream::connect((std::net::Ipv4Addr::LOCALHOST,target)).await.unwrap();joins.push(tokio::spawn(async move{let _=tokio::io::copy_bidirectional(&mut inbound,&mut outbound).await;}));}for join in joins{join.await.unwrap();}});
    let source=tokio::spawn(async move{let mut peer=CommonPeer::open(boot,boot_config).await;let packet=peer.next().await.unwrap();let call=decode_request(&packet[1..]).unwrap();assert_eq!(call.method,b"getAppConfigs.AccountEntry.Account");peer.send(&[reply(call.call_id,&bootstrap_user_entry())]).await;peer.no_more_common().await;});
    let sdk=tokio::spawn(async move{let mut peer=CommonPeer::open(main,main_config).await;let packet=peer.next().await.unwrap();let call=decode_request(&packet[1..]).unwrap();assert_eq!(call.method,b"loginSession.AccountEntry.Account");peer.send(&[reply(call.call_id,&if mode>=10{login_result_for_account()}else{login_result()})]).await;let(_,flag)=hosting_call(&mut peer).await;assert_eq!(flag,b"4");let(_,flag)=hosting_call(&mut peer).await;assert_eq!(flag,b"3");logout_peer(peer).await;});
    let resolver=tokio::spawn(async move{let mut peer=CommonPeer::open(auxiliary,config).await;let packet=peer.next().await.unwrap();assert_eq!(packet[0],0);let call=decode_request(&packet[1..]).unwrap();assert_eq!(call.method,b"aidToUid.UserEntry.User");assert_eq!(call.metadata.iter().find(|p|p.key==b"id").unwrap().value,b"prefix/UserEntry");assert_eq!(call.metadata.iter().find(|p|p.key==b"token").unwrap().value,b"fixture-auth");assert_eq!(call.metadata.iter().find(|p|p.key==b"DeviceInfo.CC").unwrap().value,b"fixture-cc");assert!(!call.metadata.iter().any(|p|p.key==b"pwd"));let mut args=Reader::versioned(call.arguments).unwrap();assert_eq!(args.u32().unwrap(),1);assert_eq!(args.bytes().unwrap(),b"phone");assert_eq!(args.bytes().unwrap(),b"+12345");args.finish().unwrap();let id=call.call_id;seen.send(()).unwrap();
        if mode<5||mode==8||mode==9||mode==10{let packet=if mode==8{let raw=encode_reply(id,7,&[0]).unwrap();let mut p=vec![1];p.extend_from_slice(raw.expose_to_transport());p}else{reply(id,&answer(if mode==10{0}else{mode}))};if mode==9{peer.send(&[packet,vec![1,0]]).await;}else{peer.send(&[packet]).await;}}peer.no_more_common().await;});
    if mode>=10{accounts::check(&cert.root,port,submitted,mode==11).await;tokio::time::timeout(Duration::from_secs(4),async{source.await.unwrap();sdk.await.unwrap();resolver.await.unwrap();relay.await.unwrap();}).await.unwrap();return;}
    let p=RuntimeProfile::supplied_common_bootstrap(bootstrap_inputs(),bootstrap_common(&cert.root,port),bootstrap_route()).unwrap();let connector=Arc::new(LegacyDenied{calls:AtomicUsize::new(0)});let(backend,mut events)=NativeHostingBackend::new(p,connector.clone());let who=owner();backend.login(who.clone(),SdkLoginRequest{server_address:BOOTSTRAP_SDK,..request(&cert.root)}).await.unwrap();let parent=backend.original_scope(&who).unwrap();backend.pause_original_polls_for_test(&who,&parent,true).unwrap();let login=tokio::time::timeout(Duration::from_secs(4),events.recv()).await.unwrap().unwrap();assert!(matches!(login.payload,BackendEventPayload::Callback(c)if c.callback==(Callback::SdkLogin{success:true})));backend.update_status(who.clone(),STATUS_REGISTER,gateway()).await.unwrap();
    let gate=ImReceiptGate::fresh();let action=UserEntryAction::original(who.clone(),parent.clone(),gate,Instant::now()+Duration::from_secs(3),b"[phone:+12345@account-domain.invalid]").unwrap();let attempt=backend.original(&who).unwrap();let mut lookup=Box::pin(backend.resolve_user_entry(action));
    if mode==6||mode==7{tokio::select!{_=submitted=>(),result=&mut lookup=>panic!("submitted resolver returned too early: {result:?}")};assert_eq!(attempt.user_entries.active(),1);if mode==6{drop(lookup);}else{let stopping=backend.update_status(who.clone(),STATUS_UNREGISTER,gateway());let(result,stop)=tokio::join!(lookup,stopping);assert_eq!(result.err(),Some("app_account_user_entry_scope_invalid"));stop.unwrap();}}
    else{let result=lookup.await;match mode{0=>assert_eq!(result.unwrap().report,"reported"),1|8=>assert_eq!(result.unwrap().report,"rejected"),2=>assert_eq!(result.unwrap().report,"unreported"),3|9=>assert_eq!(result.err(),Some("app_account_user_entry_reply_invalid")),4=>assert_eq!(result.err(),Some("app_account_user_entry_ambiguous")),5=>assert_eq!(result.err(),Some("app_account_user_entry_timeout")),_=>unreachable!()};}
    assert!(parent.is_open(),"auxiliary READ cannot retire healthy SDK");assert_eq!(attempt.user_entries.active(),0);assert_eq!(attempt.user_entries.retained_bytes(),0);assert_eq!(connector.calls.load(Ordering::SeqCst),0);if mode!=7{backend.update_status(who.clone(),STATUS_UNREGISTER,gateway()).await.unwrap();}backend.logout(who.clone()).await.unwrap();assert!(!parent.is_open());assert!(lock(&attempt.state).released);tokio::time::timeout(Duration::from_secs(4),async{source.await.unwrap();sdk.await.unwrap();resolver.await.unwrap();relay.await.unwrap();}).await.unwrap();
}
